  ('antique-cars-68', 'DC-003', 'antique cars', null, 'FunX', 'Die-Cast Vehicles', '3+', null, null, false, 0.0, null, 0),
  ('ford-rapter-69', 'DC-004', 'Ford Rapter', 'Experience the powerful look of the Ford Raptor toy car, inspired by the famous off-road pickup design. Featuring realistic details, attractive styling, and durable construction, it is perfect for children who love adventure vehicles. This miniature model encourages imaginative racing and outdoor exploration play while also making a great collectible item for car lovers.', 'FunX', 'Die-Cast Vehicles', '6+', 'Die Cast Metal + Plastic Parts', null, false, 1200.0, null, 1),
  ('rolls-royce-70', 'DC-005', 'rolls royce', 'Enjoy luxury-inspired design with this Rolls Royce miniature toy car. Featuring an elegant appearance and realistic detailing, it brings the beauty of a premium vehicle into a compact collectible form. Perfect for kids'' imaginative play, car collections, and decoration, this stylish toy makes a great gift for automobile fans and collectors.', 'FunX', 'Die-Cast Vehicles', null, 'Die Cast Metal + Plastic Parts', null, false, 1200.0, null, 1),
  ('lzxvs-71', 'DC-006', 'lzxvs', 'The LZXVS toy/product features an attractive design with fun and engaging details for children and collectors. Designed for entertainment and creative play, it provides an enjoyable experience while adding variety to your toy collection. Its unique appearance makes it a suitable choice for gifting and everyday fun.', 'FunX', 'Die-Cast Vehicles', null, 'Die Cast Metal + Plastic Parts', null, false, 1200.0, null, 1),
  ('skateboard-72', 'OS-001', 'skateboard', 'Enjoy outdoor fun and active play with this Skateboard. Designed for beginners and young riders, it helps improve balance, coordination, and confidence while providing an exciting experience. Featuring a durable board design and smooth movement, it is suitable for recreational use and learning new skills. A perfect choice for kids who enjoy adventure and outdoor activities.', 'FunX', 'Outdoor & Sports', null, 'Wood + PU Wheels + Metal Axle', null, false, 1200.0, null, 1);
