-- FunX Universe — Product catalog rebuild, Phase 1: clean product import
-- Run this once in the Supabase SQL editor (Project > SQL Editor > New query).
--
-- What this does, in order:
--   1. Adds the columns the new catalog needs (sku, category, age_group),
--      and renames two existing columns to match ecommerce-standard naming
--      (electronic -> is_electronic, stock -> quantity). Every other
--      existing column (images, badge, rating, reviews, video_url,
--      sort_order, is_new/is_trending/is_collectible/is_sale, box
--      dimensions, weight, line, universe, type) is left in place,
--      untouched and nullable — nothing is dropped, so a later phase can
--      still add photos/badges/ratings to these same rows without another
--      schema change.
--   2. Deletes every existing row (full replace, not a merge). This
--      cascades to `wishlists` (its product_id has ON DELETE CASCADE),
--      which is expected: old wishlist entries point at product ids that
--      won't exist after this replace anyway.
--   3. Imports all 72 rows from FunX_products_complete.csv.
--
-- This does NOT touch RLS policies (has_module('products') checks stay
-- exactly as they are — policies attach to the table, not to columns) or
-- any other table.

-- ── 1. Schema ────────────────────────────────────────────────────────────
alter table public.products rename column electronic to is_electronic;
alter table public.products rename column stock to quantity;

alter table public.products
  add column if not exists sku text,
  add column if not exists category text,
  add column if not exists age_group text;

do $$ begin
  alter table public.products add constraint products_sku_unique unique (sku);
exception when duplicate_object then null;
end $$;

-- ── 2. Full replace ──────────────────────────────────────────────────────
delete from public.products;

-- ── 3. Import ────────────────────────────────────────────────────────────

